import java.util.*;

import lombok.*;
import lombok.extern.slf4j.Slf4j;

public class Main {
    public static void main(String[] args) {
        Transfer t = new Transfer();
        t.kirim("sari", "budi", 50000);
        try {
            t.kirim("sari", null, 10000);
        } catch (NullPointerException e) {
            System.out.println(e.getMessage());
        }
    }
}

@Slf4j
class Transfer {
    void kirim(@NonNull String dari, @NonNull String ke, long jumlah) {
        log.info("Transfer {} dari {} ke {}", jumlah, dari, ke);
    }
}

