import java.util.*;

import lombok.*;
import lombok.extern.slf4j.Slf4j;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        Registrasi r = new Registrasi();
        while (in.hasNextLine()) {
            String[] d = in.nextLine().split(";", -1);
            String email = d[1].isEmpty() ? null : d[1];
            try {
                r.daftar(d[0], email);
            } catch (NullPointerException e) {
                System.out.println("Gagal: " + e.getMessage());
            }
        }
    }
}

@Slf4j
class Registrasi {
    void daftar(@NonNull String nama, @NonNull String email) {
        log.info("Terdaftar {} dengan email {}", nama, email.toLowerCase());
    }
}
